from sqlalchemy import Boolean, Column, ForeignKey, Integer, JSON, String, Text, DateTime
from sqlalchemy.orm import relationship

from app.models.base import BaseModel


class NovelUpdateEvent(BaseModel):
    """Durable, user-visible update activity generated by refreshes."""

    __tablename__ = "novel_update_events"

    user_id = Column(Integer, ForeignKey("users.id", ondelete="CASCADE"), nullable=False)
    novel_id = Column(Integer, ForeignKey("novels.id", ondelete="CASCADE"), nullable=False)
    event_type = Column(String(40), nullable=False)
    chapter_count = Column(Integer, nullable=False, default=0, server_default="0")
    first_chapter_number = Column(Integer, nullable=True)
    last_chapter_number = Column(Integer, nullable=True)
    message = Column(Text, nullable=False, default="", server_default="")
    details = Column(JSON, nullable=False, default=dict, server_default="{}")
    read_at = Column(DateTime, nullable=True)
    notification_visible = Column(Boolean, nullable=False, default=True, server_default="1")

    user = relationship("User")
    novel = relationship("Novel")
